/**
 * issue #98: the smallest possible composite #89 suspension adapter,
 * letting the default runner support BOTH shipped suspending node types at
 * once:
 *   - issue #90/#97's stock fixed-Delay node (`node.type === "delay"`,
 *     `pauseType === "delay"`), opt-in via `durableFixedDelay`;
 *   - this issue's project-owned Temporal Signal Wait node
 *     (`node.type === "temporal signal wait"`), always available since it
 *     has no stock-compatibility concern (#97's opt-in reasoning was
 *     specific to reproducing stock Delay's `reset`/`flush` semantics -
 *     nothing analogous exists for a brand new node type).
 *
 * This is deliberately NOT a generic adapter registry/plugin framework -
 * it is one small, closed, project-owned composition of exactly the two
 * sub-adapters this repo ships, per the issue's explicit "KISS" scope.
 *
 * Dispatch is fully deterministic and requires no extra "which adapter
 * planned this" marker, because the two sub-adapters already produce
 * disjoint suspension `type`s:
 *   - `plan()`: each sub-adapter's own `node.type` check already makes
 *     them mutually exclusive (a node cannot be both `"delay"` and
 *     `"temporal signal wait"`) - try the (optional) Delay sub-adapter
 *     first, then the always-present Signal sub-adapter;
 *   - `resume()`: dispatches purely on `resumeInput.type` - `"timer"` was
 *     produced ONLY by the Delay sub-adapter's `plan()`, `"signal"` was
 *     produced ONLY by the Signal sub-adapter's `plan()` (see
 *     `workflows.js`'s `scheduleSuspension`, which passes `{type:
 *     suspension.type, continuation: suspension.continuation}` straight
 *     through to `resume()` unchanged) - so each sub-adapter's `resume()`
 *     is invoked only for the continuation it itself produced, exactly as
 *     the issue requires.
 */

"use strict";

const { createDelaySuspensionAdapter } = require("./delaySuspensionAdapter");
const { createSignalSuspensionAdapter } = require("./signalSuspensionAdapter");

function createDefaultSuspensionAdapter({ capture, durableFixedDelay }) {
    const delayAdapter = durableFixedDelay ? createDelaySuspensionAdapter({ capture }) : null;
    const signalAdapter = createSignalSuspensionAdapter({ capture });

    function plan(node, msg) {
        if (delayAdapter) {
            const delayDescriptor = delayAdapter.plan(node, msg);
            if (delayDescriptor) {
                return delayDescriptor;
            }
        }
        return signalAdapter.plan(node, msg);
    }

    async function resume(node, msg, resumeInput) {
        if (resumeInput && resumeInput.type === "timer") {
            if (!delayAdapter) {
                throw new Error("defaultSuspensionAdapter: resume requested for a timer suspension but durable fixed Delay (options.durableFixedDelay) is not enabled on this worker");
            }
            return delayAdapter.resume(node, msg, resumeInput);
        }
        return signalAdapter.resume(node, msg, resumeInput);
    }

    return { plan, resume };
}

module.exports = { createDefaultSuspensionAdapter };
